INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(98709, 'ruRU', '', 'Аааах, как же приятно снова ДВИГАТЬСЯ. Спасибо, $n.', 24330),
(98710, 'ruRU', '', '$n, давно не виделись, со времён Мардума. Я готов к ещё одному бою.', 24330),
(98711, 'ruRU', '', 'Нам понадобится оружие и припасы, если мы хотим выбраться отсюда. Я этим займусь, $n.', 24330),
(98712, 'ruRU', '', 'Годы и годы наедине только с голосами в голове. Я думал, что сойду с ума.', 24330),
(98720, 'ruRU', '', 'Снова привет, Линзи. Что у тебя нового?', 24330),
(98721, 'ruRU', '', 'Ох, знаешь, ничего особенного. Просто помогла перенести целый город из замёрзшего севера в населённую призраками крепость, а затем на цепь островов, кишащих демонами! Обычный рабочий день, полагаю.$b$bСейчас я почти на пенсии, так что то, что Дьюкус взял дело в свои руки — просто замечательно. Он хороший малый... хотя, пожалуй, чуточку чрезмерно привязан к своему алхимическому столу!', 24330),
(98726, 'ruRU', '', 'Признаюсь, никогда бы не подумал, что моя работа алхимиком окажется такой захватывающей!$b$bНо с кем я вообще разговариваю... ты повидал куда больше приключений, чем я!', 24330),
(98727, 'ruRU', '', 'Проснись, охотник на демонов.', 24330),
(98730, 'ruRU', '', 'У меня всё хорошо, $n. Падение Короля-лича было чудом, на которое стоило посмотреть. Если бы только все беды Нордскола решились этой победой.$b$bАх, но прошлое есть прошлое. Как же здорово, что Даларан снова на передовой новой кампании! Хотя, признаюсь, я благодарен, что сражения ведёшь ты, а не я.', 24330),
(98731, 'ruRU', '', 'Возьми своё оружие, $n. Полагаю, ты всё ещё умеешь обращаться с клинком.', 24330),
(98734, 'ruRU', '', 'Мне понадобится твоя помощь, чтобы остановить Гул''дана. Освободи остальных иллидари, быстро!', 24330),
(98740, 'ruRU', '', 'Сработало! $GОн жив:Она жива;!', 24330),
(98741, 'ruRU', '', 'Конечно сработало! Я будила существ, что были мертвее вдвое и дольше втрое. Этот был лёгким случаем.', 24330),
(98746, 'ruRU', '', 'Путь свободен! Поднимемся на вершину башни!', 24330),
(98747, 'ruRU', '', 'Иди вперёд, я доложу Седогриву. Удачи, защитник.', 24330),
(98748, 'ruRU', '', 'Сейчас наш шанс. Поднимемся на эту башню!', 24330),
(98749, 'ruRU', '', 'Дальше ты сам. Удачи!', 24330),
(98753, 'ruRU', '', 'Надеюсь, Майев была права, освободив тебя, охотник на демонов. Иди — я удержу рубеж.', 24330),
(98757, 'ruRU', '', 'Значит, ОН — ключ к падению Азерота.', 24330),
(98758, 'ruRU', '', 'Мы организовали для тебя прямой перелёт в Даларан, Верховный лорд.', 24330),
(98779, 'ruRU', '', 'С удовольствием! Взгляни на мой товар, $n.', 24330),
(98781, 'ruRU', '', 'Да, да... Мы все знаем, как ты привязан к своему алхимическому столу!', 24330),
(98782, 'ruRU', '', 'Эй, ты жив!', 24330),
(98806, 'ruRU', '', 'Держать строй, охотники на демонов. Мы сражаемся во имя лорда Иллидана!', 24330),
(98814, 'ruRU', '', 'Просмотреть доступные задания.', 24330),
(98826, 'ruRU', '', '[TEMP] Click on each gossip option to view half of the available zone options. You can only pick one of the four available initially. This will eventually be on the mission map.', 24330),
(98836, 'ruRU', '', 'Чувствую себя отлично. [PH]', 24330),
(98838, 'ruRU', '', 'Эта дорога небезопасна, искатель приключений.\n\nКобольды напали на наш караван и сбежали с камерами душ, которые мы должны были доставить Аллари для допроса.', 24330),
(98839, 'ruRU', '', 'Я почту память Урии, доставив камеры душ Аллари, как и было запланировано.', 24330),
(98845, 'ruRU', '', 'Мне нужно идти. Кейн позвал меня разобраться кое с чем. Наверное, ему нужна помощь убить демона.', 24330),
(98848, 'ruRU', '', 'В последний раз, когда я видел, Кор''вас прокладывала путь разрушения через мост.', 24330),
(98849, 'ruRU', '', 'Что бы ты ни выбрал, будет приятно обратить ещё больше силы Легиона против них самих.', 24330),
(98850, 'ruRU', '', 'Кем бы ты ни был, теперь ты в моей паутине.', 24330),
(98851, 'ruRU', '', 'Твоя попытка завладеть краеугольным камнем моего повелителя Саргераса обречена на провал.', 24330),
(98861, 'ruRU', '', 'Много веков назад я была вождём племени Небесного Рога. Никогда прежде я не видела подобного осквернения нашего древнего места погребения!', 24330),
(98887, 'ruRU', '', 'Вместе мы снова заточим этих демонов.', 24330),
(98892, 'ruRU', '', 'Я жив!', 24330),
(98895, 'ruRU', '', 'Ах, снова дышать!', 24330),
(98898, 'ruRU', '', 'Благословляю тебя, незнакомец!', 24330),
(98901, 'ruRU', '', 'Ты заслужил мою благодарность, путник.', 24330);
